import React from 'react';
import { autoWebViewJs } from '@droid/android';
import { useProxyWatch, useTranslation } from '@fanfanlo';
import { Box, Button } from '@mui/material';
import { user } from '@app/model';

export function GoogleLoginButton() {
    const {t} = useTranslation('homepage/components/Login/content');
  const handleGoogleLogin = () => {
    console.log("Initiating Android Google Login...");
    try {
      // 调用 Android 的 FirebaseAuthManager.startGoogleLogin()
      // 不需要参数，只负责触发登录
      const script = `
        com.fanfanlo.droid.auth.FirebaseAuthManager.startGoogleLogin();
      `;

      autoWebViewJs.callScript(script);
    } catch (error) {
      console.error("Google Login initiation failed:", error);
    }
  };
  return (
    <Button onClick={handleGoogleLogin}>
      {t("GoogleLoginButton.name")}
    </Button>
  );
}

export function LoginButtonBox(){
  const [userToken] = useProxyWatch(user, 'data.storeData.user_token', user.data.storeData.user_token);
  if(userToken){
    return <></>;
  }
  return(
    <Box><GoogleLoginButton /></Box>
  )
}