import { user } from "@app/model";
import { useProxyWatch, useTranslation } from "@fanfanlo";
import { Box, Button } from "@mui/material";
import { useRouter } from "next/router";


export function AccountRemoveButton() {
  const { t } = useTranslation('homepage/components/account/remove/content');
  const router = useRouter();
  function onClick(){
    router.push('/account/remove');
  }
  return (<>
  <Button onClick={onClick}>{t('AccountRemoveButton.name')}</Button>
  </>)
}

export function AccountRemoveButtonBox(){
    const [userToken] = useProxyWatch(user, 'data.storeData.user_token', user.data.storeData.user_token)
    
    if(!userToken){
        return(<></>)}
    return(
        <Box>
            <AccountRemoveButton />
        </Box>
    )
}