import { useTranslation } from "@fanfanlo";
import { Box, Button } from "@mui/material";
import { useRouter } from "next/router";

export function PrivacyButton(){
    const {t} = useTranslation('homepage/components/privacy/content');
    const router = useRouter();
    function onClick(){
        return(
            router.push('/privacies/global-en.html')
        )
    }
    return(
        <><Button onClick={onClick}>{t("PrivacyButton.name")}</Button></>
    )
}

export function PrivacyButtonBox(){
    return (
        <Box><PrivacyButton /></Box>
    )
}